To let users upload a profile picture, you need three main components:

1. **Frontend:** An HTML form with a file input (and preferably an image preview).
2. **Backend:** An API endpoint to receive, validate, and save the file.
3. **Storage:** A place to store the file (e.g., local server disk, or cloud storage like AWS S3/Cloudinary) and a database to link the image URL to the user.

Here is a complete, production-ready example using **HTML/JavaScript** for the frontend and **Node.js (Express + Multer)** for the backend.

---

### Step 1: The Frontend (HTML & JavaScript)

This provides a clean UI with an instant image preview before uploading.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Upload Profile Picture</title>
  <style>
    .avatar-upload {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 15px;
      font-family: sans-serif;
    }
    .preview-img {
      width: 150px;
      height: 150px;
      border-radius: 50%;
      object-fit: cover;
      border: 2px solid #ccc;
    }
  </style>
</head>
<body>

<div class="avatar-upload">
  <!-- Default placeholder image -->
  <img id="preview" src="https://via.placeholder.com/150" alt="Avatar Preview" class="preview-img">

  <input type="file" id="avatarInput" accept="image/png, image/jpeg, image/webp" />
  <button onclick="uploadAvatar()">Save Picture</button>
  <p id="status"></p>
</div>

<script>
  const fileInput = document.getElementById('avatarInput');
  const preview = document.getElementById('preview');
  const status = document.getElementById('status');

  // Show a preview when the user selects a file
  fileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) {
      preview.src = URL.createObjectURL(file);
    }
  });

  // Send the file to the backend
  async function uploadAvatar() {
    const file = fileInput.files[0];
    if (!file) {
      alert("Please select a file first!");
      return;
    }

    const formData = new FormData();
    formData.append('avatar', file); // 'avatar' matches the backend field name

    status.innerText = "Uploading...";

    try {
      const response = await fetch('/api/upload-avatar', {
        method: 'POST',
        body: formData,
        // Do NOT set Content-Type header manually; the browser will set it with boundary
      });

      const result = await response.json();

      if (response.ok) {
        status.innerText = "Upload successful!";
        console.log("Image URL:", result.filePath);
      } else {
        status.innerText = "Upload failed: " + result.error;
      }
    } catch (err) {
      status.innerText = "Error uploading file.";
      console.error(err);
    }
  }
</script>

</body>
</html>
```

---

### Step 2: The Backend (Node.js + Express)

Install the required packages:
```bash
npm install express multer
```

Create a file named `server.js`:

```javascript
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');

const app = express();

// Ensure 'uploads' directory exists
const uploadDir = path.join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir);
}

// Serve uploaded images statically so they can be viewed
app.use('/uploads', express.static('uploads'));

// 1. Configure Storage
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, 'uploads/');
  },
  filename: (req, file, cb) => {
    // Generate unique name: avatar-timestamp-random.ext
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    cb(null, 'avatar-' + uniqueSuffix + path.extname(file.originalname));
  }
});

// 2. Validate File Type and Size
const upload = multer({
  storage: storage,
  limits: { fileSize: 2 * 1024 * 1024 }, // 2 MB limit
  fileFilter: (req, file, cb) => {
    // Accept only standard image types
    const allowedTypes = /jpeg|jpg|png|webp/;
    const ext = allowedTypes.test(path.extname(file.originalname).toLowerCase());
    const mime = allowedTypes.test(file.mimetype);

    if (ext && mime) {
      cb(null, true);
    } else {
      cb(new Error('Only JPEG, PNG, and WebP images are allowed.'));
    }
  }
});

// 3. The Upload Route
app.post('/api/upload-avatar', upload.single('avatar'), (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'Please upload a file' });
    }

    const filePath = `/uploads/${req.file.filename}`;

    // TODO: Save `filePath` to your database for the currently logged-in user
    // e.g., await User.findByIdAndUpdate(userId, { avatar: filePath });

    res.json({ message: 'Success', filePath: filePath });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Error handling middleware for Multer (e.g., file too large)
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    return res.status(400).json({ error: `Upload error: ${err.message}` });
  } else if (err) {
    return res.status(400).json({ error: err.message });
  }
  next();
});

app.listen(3000, () => console.log('Server running on http://localhost:3000'));
```

---

### Important Best Practices for Production

1. **Do not save files directly to the web server in production:**
   If you host your site on platforms like Heroku, Render, AWS ECS, or Vercel, the local filesystem is **ephemeral** (temporary). Files will be erased whenever the server restarts or redeploys. Use cloud storage instead:
   * **AWS S3** (using `@aws-sdk/client-s3` and `multer-s3`)
   * **Cloudinary** (automatically optimizes and crops profile pictures)
   * **Supabase / Firebase Storage**
2. **Resize/Compress Images:** Profile pictures should rarely be larger than 400x400 pixels. Use a library like [`sharp`](https://www.npmjs.com/package/sharp) on the backend to crop and compress them before saving.
3. **Authentication:** Protect the upload route using your authentication middleware (JWT, sessions, etc.) so that only the authenticated user can update their profile.

